package com.aoo.bcg.identity;
import com.fasterxml.jackson.databind.ObjectMapper;import java.net.URI;import java.net.http.*;import java.time.Duration;import java.util.Map;
/** Production SMS adapter: a non-2xx upstream response fails the challenge transaction. */
public final class HttpPhoneCodeSender implements PhoneCodeSender {private final HttpClient client;private final URI endpoint;private final String token;private final ObjectMapper json;public HttpPhoneCodeSender(URI endpoint,String token,ObjectMapper json){this.client=HttpClient.newBuilder().connectTimeout(Duration.ofSeconds(5)).build();this.endpoint=endpoint;this.token=token;this.json=json;}public void send(String phone,String code,String businessId){try{byte[] body=json.writeValueAsBytes(Map.of("phone",phone,"code",code,"businessId",businessId,"template","IDENTITY_PHONE_VERIFY"));var request=HttpRequest.newBuilder(endpoint).timeout(Duration.ofSeconds(8)).header("Authorization","Bearer "+token).header("Content-Type","application/json").POST(HttpRequest.BodyPublishers.ofByteArray(body)).build();var response=client.send(request,HttpResponse.BodyHandlers.discarding());if(response.statusCode()<200||response.statusCode()>=300)throw new IllegalStateException("sms provider rejected request");}catch(InterruptedException e){Thread.currentThread().interrupt();throw new IllegalStateException("sms provider interrupted",e);}catch(Exception e){throw e instanceof IllegalStateException i?i:new IllegalStateException("sms provider unavailable",e);}}}
